contents.plugin.json:
{
  "$schema": "https://agent-plugins.org/schemas/1.0.0/plugin.schema.json",
  "author": {
    "email": "shfwin6@gmail.com",
    "name": "Hongfei Shang"
  },
  "description": "连接并管理你授权的 Linux 和 macOS 设备。查看设备状态、执行终端命令、读写文件和管理进程，操作在选定设备上运行。",
  "extensions": {
    "com.openai": {
      "interface": {
        "brandColor": "#52677D",
        "brandColorDark": "#A5B5C5",
        "capabilities": [],
        "category": "Other",
        "composerIcon": "./assets/remote-device-hub-theme-light-256.png",
        "composerIconDark": "./assets/remote-device-hub-theme-dark-256.png",
        "defaultPrompt": null,
        "developerName": "Hongfei Shang",
        "displayName": "Remote Device Hub",
        "logo": "./assets/remote-device-hub-theme-light-512.png",
        "logoDark": "./assets/remote-device-hub-theme-dark-512.png",
        "longDescription": "连接并管理你授权的 Linux 和 macOS 设备。查看设备状态、执行终端命令、读写文件和管理进程，操作在选定设备上运行。",
        "shortDescription": "安全远程管理 Linux 与 macOS 设备"
      },
      "apps": "./.app.json",
      "requires_local_executor": false
    }
  },
  "name": "remote-device-hub",
  "version": "1.2.3"
}
